answers = []
for s in sources:
    n = s['number']
    m = metadata[n]
    obj = {k: s[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    obj.update(proposed_xml=proposals[n], reason=m['reason'], review_notes=m['review_notes'], status='rewrite_draft', substantive_impact=m['impact'])
    if 'changes' in m:
        obj.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=m['changes'])
    if n == '223 U':
        obj.update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope="Habilitation réglementaire générale à imposer des déclarations à la mère et aux filiales pour les exercices ouverts à compter de l'entrée en vigueur ; obligations ayant un fondement législatif autonome et anciennes périodes réservées.")
    required = refs['requirements'][s['code_id'] + '|' + s['source_id']]
    obj['reference_checks'] = []
    for target in required:
        t = refs['targets'][target]
        assessment = L_checks[t['number']] if n == '223 L' else T_check if n == '223 T' else U_check
        obj['reference_checks'].append(dict(target_key=target, view_sha256=t['view_sha256'], assessment=assessment))
    if s.get('benefit_check_required'):
        raise RuntimeError('Specific benefit review must be supplied')
    answers.append(obj)

Path('answer.json').write_text(json.dumps(answers, ensure_ascii=False, indent=2) + '\n')
print(json.dumps({'output_file': 'answer.json', 'article_count': len(answers)}, ensure_ascii=False))
